/**
 * Storage abstraction for private files. Application code depends only on this interface; the driver is chosen by
 * `STORAGE_DRIVER`. Keys are generated by the server (never derived from user input) and every driver must refuse
 * keys that are not plain relative `a/b/c` paths. Files are private: they are only ever returned through an
 * authorized route handler, never through a public URL.
 */
export interface StoredObject {
  bytes: Uint8Array;
}

/**
 * Optional capability of object-storage drivers: let the browser exchange bytes with the bucket directly through short-lived
 * signed URLs, so large files never pass through the (size-limited, serverless) application. Authorization always happens
 * in the application before a URL is issued; the bucket itself stays private.
 */
export interface DirectAccess {
  /** Size of the stored object, or null when it does not exist. */
  head(key: string): Promise<{ size: number } | null>;
  /** A URL the browser can PUT exactly `size` bytes of `contentType` to, for `expiresSeconds`. */
  presignPut(key: string, o: { contentType: string; size: number; expiresSeconds: number }): Promise<{ url: string; headers: Record<string, string> }>;
  /** A URL the browser can GET once authorized; the response is forced to download with the given disposition and type. */
  presignGet(key: string, o: { contentType: string; disposition: string; expiresSeconds: number }): Promise<string>;
}

export interface Storage {
  /** Stores new content under `key`. Fails if the key already exists (objects are immutable). */
  put(key: string, bytes: Uint8Array): Promise<void>;
  get(key: string): Promise<StoredObject | null>;
  /** Removes an object. Missing objects are not an error. */
  remove(key: string): Promise<void>;
  /** Present only on object-storage drivers (S3-compatible). The local development driver has none. */
  direct?: DirectAccess;
}

const KEY = /^[a-z0-9][a-z0-9-]*(\/[a-z0-9][a-z0-9-]*){0,4}$/;

/** Throws unless `key` is a short relative path of lowercase letters, digits and hyphens (no dots, no traversal). */
export function assertSafeKey(key: string): void {
  if (!KEY.test(key) || key.length > 200) throw new Error("Unsafe storage key");
}
